style.css:
@-moz-document domain("ejemplo.com") {
/* Aplica solo a ejemplo.com */

/* Selector de cuerpo */
body {
    background-color: #f0f0f0; /* Fondo gris claro */
    font-family: sans-serif; /* Fuente genérica sans-serif */
    color: #333; /* Texto oscuro */
}

/* Selector de encabezado */
h1 {
    color: #0056b3; /* Azul para los títulos H1 */
    border-bottom: 2px solid #0056b3; /* Línea azul debajo */
    padding-bottom: 10px;
}

/* Selector de clase */
.menu-principal {
    background-color: #333; /* Fondo negro para el menú */
    padding: 15px;
    border-radius: 8px; /* Bordes redondeados */
}

/* Selector de ID */
#logo {
    filter: grayscale(100%); /* Convierte el logo en blanco y negro */
}

/* Puedes combinar selectores con comas */
p, a {
    line-height: 1.6; /* Espaciado entre líneas */
}

/* Ejemplo de cómo ocultar algo */
/* .publicidad {
    display: none !important;
} */
}
